/// Undo of the single latest accepted non-compensating operation
/// (docs/ux-04-trustworthy-undo.md §3.2/§3.3). Eligibility is store-owned;
/// this admission only guards lifecycle (halted/stopping/disconnecting)
/// and the active account. Cancelling a still-queued operation is purely
/// local; compensating operations recheck capability in the unchanged
/// executor, so no mutation-access gate is applied here.
pub fn undo_operation(&self, command: &UndoOperation) -> Result<UndoReceipt, MailError> {
    let inner = &*self.inner;
    let mut st = inner.ctrl.state.lock().map_err(storage_err())?;
    if st.halted || st.stop {
        return Err(MailError::StorageUnavailable);

            return Err(MailError::StorageUnavailable);
        }
        if st.disconnecting {
            return Err(MailError::Busy);
        }
        match inner.store.account() {
            Ok(Some(_)) => {}
            Ok(None) => return Err(MailError::AuthRequired),
            Err(error) => {
                if latch_admission_storage_error(&mut st, &inner.ctrl, &error) {
                    drop(st);
                    inner.hub.dispatch();
                }
                return Err(error);
            }
        }
        let receipt = match inner.store.undo_operation(command) {
            Ok(receipt) => receipt,
            Err(error) => {
                if error == MailError::StorageUnavailable {
                    st.halted = true;
                    st.error = Some(error.clone());
                    st.pass_cancel.cancel();
                    cancel_independent_reads(&mut st);
                    inner.ctrl.wake.notify_all();
                }
                return Err(error);
            }
        };
        // Compensation work must dispatch immediately; a cancelled operation
        // needs no worker pass but the wake is harmless.
        st.operations_requested = true;
        inner.ctrl.wake.notify_all();
        drop(st);
        inner.hub.dispatch();
        Ok(receipt)
    }

    /// One partial group Undo attempt (docs/ux-05-safe-bulk-processing.md §5).
    /// Same admission as the single undo: lifecycle guard and active account;
    /// whole-group eligibility is store-owned. Compensation work dispatches
    /// immediately after the single acceptance commit.
    pub fn undo_operation_group(
        &self,
        command: &crate::groups::UndoOperationGroup,
    ) -> Result<crate::groups::GroupUndoReceipt, MailError> {
        let inner = &*self.inner;
        let mut st = inner.ctrl.state.lock().map_err(storage_err())?;
        if st.halted || st.stop {
            return Err(MailError::StorageUnavailable);
        }
        if st.disconnecting {
            return Err(MailError::Busy);
        }
        match inner.store.account() {
            Ok(Some(_)) => {}
            Ok(None) => return Err(MailError::AuthRequired),
            Err(error) => {
                if latch_admission_storage_error(&mut st, &inner.ctrl, &error) {
                    drop(st);
                    inner.hub.dispatch();
                }
                return Err(error);
            }
        }
        let receipt = match inner.store.undo_operation_group(command) {
            Ok(receipt) => receipt,
            Err(error) => {
                if error == MailError::StorageUnavailable {
                    st.halted = true;
                    st.error = Some(error.clone());
                    st.pass_cancel.cancel();
                    cancel_independent_reads(&mut st);
                    inner.ctrl.wake.notify_all();
                }
                return Err(error);
            }
        };
        // Compensation work must dispatch immediately; cancelled members
        // need no worker pass but the wake is harmless.
        st.operations_requested = true;
        inner.ctrl.wake.notify_all();
        drop(st);
        inner.hub.dispatch();
        Ok(receipt)
    }

    /// Cached acceptance keeps its single capability check. Only missing exact
    /// references leave the locks for a provider read and then repeat admission.
    fn accept_action<T>(
        &self,
        account: &str,
        request: &str,
        members: &[ConversationRef],
        accept: impl Fn(&GmailStore, Option<&super::store::SearchObservation>) -> Result<T, MailError>,
    ) -> Result<T, MailError> {
        crate::groups::validate_group_request_id(request)?;
        crate::groups::validate_group_members(account, members)?;
        let (ready, missing, generation) = self.accept_operation(|store| {
            let generation = store.generation()?;
            let observation = super::store::SearchObservation::Cached {
                generation,
                members: members.to_vec(),
            };
            let missing = store.missing_action_context(account, request, members)?;
            if missing.is_empty() {
                // Fence concurrent eviction between the context check and the
                // acceptance transaction, even when no provider read is needed.
                Ok((
                    Some(accept(store, Some(&observation))?),
                    missing,
                    generation,
                ))
            } else {
                Ok((None, missing, generation))
            }
        })?;
        if let Some(receipt) = ready {
            return Ok(receipt);
        }
        // Keep offline and per-member missing semantics; no inferred targets.
        if self
            .inner
            .ctrl
            .state
            .lock()
            .map_err(storage_err())?
            .connection
            != ConnectionState::Connected
        {
            // Missing members must keep their ordinary per-member rejection,
            // but the deferred command still belongs to its original lifecycle.
            let observation = super::store::SearchObservation::Cached {
                generation,
                members: vec![],
            };
            return self.accept_operation(|store| accept(store, Some(&observation)));
        }
        let work = self.begin_reply_enrichment()?;
        // Register lifecycle cancellation before checking the ORIGINAL generation:
        // a disconnect in the preflight/registration gap must not revive this setter.
        if self.inner.store.generation()? != generation || work.cancel.is_cancelled() {
            return Err(MailError::NotFound);
        }
        let revision = self.inner.store.observation_revision()?;
        let threads = fetch_changed_threads(self.inner.provider.as_ref(), &missing, &work.cancel)?
            .into_iter()
            .filter_map(|fetch| match fetch {
                ThreadFetch::Cached(thread) => Some(*thread),
                ThreadFetch::Missing(_) => None,
            })
            .collect();
        if work.cancel.is_cancelled() {
            return Err(MailError::NotFound);
        }
        let observation = super::store::SearchObservation::Fetched {
            generation,
            revision,
            threads,
        };
        self.accept_operation(|store| accept(store, Some(&observation)))
    }

    fn accept_operation<T>(
        &self,
        accept: impl FnOnce(&GmailStore) -> Result<T, MailError>,
    ) -> Result<T, MailError> {
        let inner = &*self.inner;
        let mut st = inner.ctrl.state.lock().map_err(storage_err())?;
        if st.halted || st.stop {
            return Err(MailError::StorageUnavailable);
        }
        if st.disconnecting {
            return Err(MailError::Busy);
        }
        let mutation_access = match inner.provider.mutation_access() {
            Ok(access) => access,
            Err(error) => {
                if latch_admission_storage_error(&mut st, &inner.ctrl, &error) {
                    drop(st);
                    inner.hub.dispatch();
                }
                return Err(error);
            }
        };
        if !mutation_access {
            return Err(MailError::PermissionRequired);
        }
        match inner.store.account() {
            Ok(Some(_)) => {}
            Ok(None) => return Err(MailError::AuthRequired),
            Err(error) => {
                if latch_admission_storage_error(&mut st, &inner.ctrl, &error) {
                    drop(st);
                    inner.hub.dispatch();
                }
                return Err(error);
            }
        }
        let receipt = match accept(&inner.store) {
            Ok(receipt) => receipt,
            Err(error) => {
                if error == MailError::StorageUnavailable {
                    st.halted = true;
                    st.error = Some(error.clone());
                    st.pass_cancel.cancel();
                    cancel_independent_reads(&mut st);
                    inner.ctrl.wake.notify_all();
                }
                return Err(error);
            }
        };
        st.operations_requested = true;
        inner.ctrl.wake.notify_all();
        drop(st);
        inner.hub.dispatch();
        Ok(receipt)
    }

    /// Enqueues a connect attempt and returns void acceptance immediately;
    /// OAuth/sync success is observed through [`Self::account_status`]
    /// (`authenticating`, then `connected` or an error hint). A missing
    /// client configuration is a typed, visible rejection.
    pub fn connect_account(&self) -> Result<(), MailError> {
        let inner = &*self.inner;
        if !inner.provider.is_configured() {
            return Err(MailError::NotConfigured);
        }
        let mut st = inner.ctrl.state.lock().map_err(storage_err())?;
        if st.halted || st.stop {
            return Err(MailError::StorageUnavailable);
        }
        if st.disconnecting {
            return Err(MailError::Busy);
        }
        if st.pass_in_flight {
            return Err(MailError::Busy);
        }
        st.auth_requested = true;
        st.auth_kind = AuthKind::Connect;
        st.auth_auto_retry = false;
        st.connection = ConnectionState::Authenticating;
        inner.ctrl.wake.notify_all();
        drop(st);
        inner.hub.dispatch();
        Ok(())
    }

    /// Cancels in-flight auth/sync, securely deletes credentials via the
    /// provider, and clears the account/cache before returning. Stale
    /// in-flight results lose the race by generation guard and can never
    /// repopulate the cache. Failures are typed and visible; nothing is
    /// cleared unless credential deletion succeeded.
    pub fn disconnect_account(&self) -> Result<(), MailError> {
        let inner = &*self.inner;
        let _serial = inner.disconnect_lock.lock().map_err(storage_err())?;
        // Publish an admission barrier and cancellation together. The worker
        // cannot activate another pass until credentials and cache are cleared.
        {
            let mut st = inner.ctrl.state.lock().map_err(storage_err())?;
            st.disconnecting = true;
            st.auth_requested = false;
            st.auth_auto_retry = false;
            st.sync_requested = false;
            st.operations_requested = false;
            st.upgrade_requested = false;
            st.pass_cancel.cancel();
            cancel_independent_reads(&mut st);
            inner.ctrl.wake.notify_all();
        }
        let cleanup = (|| {
            // Stale-guard first: any result from a pass that raced this
            // disconnect is discarded by the store's generation check.
            inner.store.advance_generation()?;
            inner.ctrl.wait_until_idle(DISCONNECT_IDLE_TIMEOUT)?;
            // Local secure credential deletion; fail closed without clearing.
            inner.provider.disconnect()?;
            inner.store.clear_account()
        })();
        // If cleanup failed, the account/operation rows remain. Any setter
        // whose completion raced the generation advance must be reconciled,
        // never left permanently applying or replayed as a POST.
        let interrupted = if cleanup.is_err() {
            inner.store.recover_interrupted_operations()
        } else {
            Ok(false)
        };
        {
            let mut st = inner.ctrl.state.lock().map_err(storage_err())?;
            st.disconnecting = false;
            st.upgrade_in_flight = false;
            st.active_action = None;
            match &cleanup {
                Ok(()) => {
                    st.connection = ConnectionState::Disconnected;
                    st.error = None;
                    st.backoff = 0;
                }
                Err(error) => {
                    st.error = Some(error.clone());
                    match interrupted {
                        Ok(true) => st.operations_requested = true,
                        Ok(false) => {}
                        Err(storage_error) => {
                            st.halted = true;
                            st.error = Some(storage_error.clone());
                            st.pass_cancel.cancel();
                            cancel_independent_reads(&mut st);
                        }
                    }
                }
            }
            inner.ctrl.wake.notify_all();
        }
        inner.hub.dispatch();
        cleanup
    }

    /// Enqueues one catch-up pass. Repeated requests coalesce; a request
    /// while a pass is in flight is rejected typed as `busy` so there is
    /// never a concurrent cursor writer.
    pub fn request_sync(&self) -> Result<(), MailError> {
        let mut st = self.inner.ctrl.state.lock().map_err(storage_err())?;
        if st.halted || st.stop {
            return Err(MailError::StorageUnavailable);
        }
        if st.disconnecting {
            return Err(MailError::Busy);
        }
        if st.pass_in_flight {
            return Err(MailError::Busy);
        }
        match st.connection {
            ConnectionState::NotConfigured => Err(MailError::NotConfigured),
            ConnectionState::Authenticating => Err(MailError::Busy),
            ConnectionState::Disconnected | ConnectionState::AuthRequired => {
                Err(MailError::AuthRequired)
            }
            ConnectionState::Connected => {
                st.sync_requested = true;
                self.inner.ctrl.wake.notify_all();
                Ok(())
            }
        }
    }

    /// Registers a change listener and returns an unsubscribe handle. The
    /// listener is a change hint, not a payload; guard lifetime matches the
    /// fixture slice (fires until unsubscribed or dropped).
    pub fn subscribe(&self, listener: impl Fn() + Send + Sync + 'static) -> GmailUnsubscribe {
        let id = self.inner.next_listener_id.fetch_add(1, Ordering::SeqCst);
        self.inner
            .hub
            .listeners
            .lock()
            .expect("gmail listener hub poisoned")
            .insert(id, Arc::new(listener));
        GmailUnsubscribe {
            id,
            hub: Arc::clone(&self.inner.hub),
        }
    }

    /// Requests worker shutdown, cancels any in-flight provider call, and
    /// joins the worker thread with a bounded wait. Interrupted discovery or
    /// history work stays durable and resumes at the next launch.
    pub fn stop(&self) {
        self.inner.shutdown();
    }
}

        self.shutdown();
    }
}

fn credentialless_connection(has_account: bool) -> ConnectionState {
    if has_account {
        ConnectionState::AuthRequired
    } else {
        ConnectionState::Disconnected
    }
}

fn is_auth_failure(error: &MailError) -> bool {
    matches!(
        error,
        MailError::AuthRequired | MailError::AuthFailed | MailError::SecretsUnavailable
    )
}

fn is_retryable_network(error: &MailError) -> bool {
    matches!(
        error,
        MailError::NetworkUnavailable
            | MailError::RateLimited
            | MailError::ProviderUnavailable
            | MailError::InvalidProviderResponse
    )
}

/// Connection state after a failed auth attempt. Network-type failures for a
/// user-initiated connect map to `disconnected` (no silent auto-retry of the
/// browser flow); the typed error stays visible in the status.
fn auth_failure_connection(error: &MailError) -> ConnectionState {
    match error {
        MailError::NotConfigured => ConnectionState::NotConfigured,
        MailError::AuthRequired | MailError::AuthFailed | MailError::SecretsUnavailable => {
            ConnectionState::AuthRequired
        }
        _ => ConnectionState::Disconnected,
    }
}

fn backoff_delay(backoff: u32) -> Duration {
    let factor = 2u32.saturating_pow(backoff.min(8));
    PERIODIC_INTERVAL
        .checked_mul(factor)
        .map(|delay| delay.min(MAX_BACKOFF_INTERVAL))
        .unwrap_or(MAX_BACKOFF_INTERVAL)
}

// Per-worker time compression for lifecycle tests; production uses real durations.
fn worker_wait(_state: &CtrlState, wait: Duration) -> Duration {
    #[cfg(test)]
    {
        wait / _state.wait_divisor
    }
    #[cfg(not(test))]
    {
        wait
    }
}

// ------------------------------------------------------------------- worker

fn spawn_worker(
    store: Arc<GmailStore>,
    provider: Arc<dyn GmailProvider>,
    ctrl: Arc<Ctrl>,
    hub: Arc<GmailHub>,
    profile: Arc<ProfileGuard>,
) -> Result<JoinHandle<()>, MailError> {
    std::thread::Builder::new()
        .name("gmail-sync-worker".to_string())
        .spawn(move || run(store, provider, ctrl, hub, profile))
        .map_err(storage_err())
}

fn run(
    store: Arc<GmailStore>,
    provider: Arc<dyn GmailProvider>,
    ctrl: Arc<Ctrl>,
    hub: Arc<GmailHub>,
    // Held for the whole thread: a running or detached worker can never
    // outlive the profile lock.
    _profile: Arc<ProfileGuard>,
) {
    let mut sync_deadline = Instant::now();
    loop {
        {
            let state = ctrl.state.lock().expect("gmail ctrl poisoned");
            if state.stop || state.halted {
                return;
            }
        }
        if let Err(error) = process_due_reminders(&store, provider.as_ref(), &ctrl, &hub) {
            let mut st = ctrl.state.lock().expect("gmail ctrl poisoned");
            if latch_admission_storage_error(&mut st, &ctrl, &error) {
                drop(st);
                hub.dispatch();
                return;
            }
        }
        // Select the next action: request-driven work runs immediately,
        // tick-driven catch-up waits for the periodic/backoff interval.
        let (action, pass_cancel) = {
            let mut st = ctrl.state.lock().expect("gmail ctrl poisoned");
            while st.disconnecting && !st.stop {
                st = ctrl.wake.wait(st).expect("gmail ctrl poisoned");
            }
            if st.stop || st.halted {
                return;
            }
            #[cfg(test)]
            {
                if st.test_tick_due {
                    sync_deadline = Instant::now();
                    st.test_tick_due = false;
                }
                st.test_sync_deadline = Some(sync_deadline);
                st.test_wait_cycles += 1;
                ctrl.wake.notify_all();
            }
            let mut tick_due = Instant::now() >= sync_deadline;
            let runnable_request = |st: &CtrlState| {
                st.auth_requested
                    || (st.connection == ConnectionState::Connected
                        && (st.upgrade_requested
                            || st.sync_requested
                            || (st.operations_requested && !test_operations_paused(st))))
            };
            if !runnable_request(&st) && !st.reminder_work && !tick_due {
                // No runnable request pending: wait for one or the periodic
                // catch-up/backoff deadline.
                let reminder_wait = match store.reminder_wait() {
                    Ok(value) => value,
                    Err(error) => {
                        if latch_admission_storage_error(&mut st, &ctrl, &error) {
                            drop(st);
                            hub.dispatch();
                            return;
                        }
                        None
                    }
                };
                let reminder_deadline = reminder_wait.map(|wait| {
                    Instant::now() + worker_wait(&st, wait.max(Duration::from_secs(1)))
                });
                #[cfg(test)]
                {
                    st.test_reminder_deadline = reminder_deadline;
                    ctrl.wake.notify_all();
                }
                let deadline = reminder_deadline.map_or(sync_deadline, |d| d.min(sync_deadline));
                loop {
                    let remaining = deadline.saturating_duration_since(Instant::now());
                    if remaining.is_zero() {
                        let now = Instant::now();
                        tick_due = now >= sync_deadline;
                        if reminder_deadline.is_some_and(|d| now >= d) {
                            st.reminder_work = true;
                        }
                        break;
                    }
                    let (guard, _) = ctrl
                        .wake
                        .wait_timeout(st, remaining)
                        .expect("gmail ctrl poisoned");
                    st = guard;
                    if st.stop || st.halted {
                        return;
                    }
                    #[cfg(test)]
                    if st.test_tick_due {
                        sync_deadline = Instant::now();
                        st.test_tick_due = false;
                        break;
                    }
                    if st.disconnecting || st.reminder_work || runnable_request(&st) {
                        break;
                    }
                }
            }
            if st.halted {
                return;
            }
            if st.disconnecting {
                drop(st);
                continue;
            }
            tick_due |= Instant::now() >= sync_deadline;
            st.reminder_work = false;
            let action = if st.auth_requested {
                st.auth_requested = false;
                PassAction::Auth(st.auth_kind)
            } else if st.connection == ConnectionState::Authenticating
                && st.auth_auto_retry
                && tick_due
            {
                PassAction::Auth(AuthKind::Restore)
            } else if st.connection == ConnectionState::Connected && st.upgrade_requested {
                st.upgrade_requested = false;
                st.upgrade_in_flight = true;
                PassAction::MutationUpgrade
            } else if st.connection == ConnectionState::Connected && st.sync_requested {
                st.sync_requested = false;
                PassAction::Sync
            } else if st.connection == ConnectionState::Connected
                && st.operations_requested
                && !test_operations_paused(&st)
            {
                st.operations_requested = false;
                PassAction::Mutations
            } else if st.connection == ConnectionState::Connected && tick_due {
                PassAction::Sync
            } else {
                if tick_due {
                    sync_deadline = Instant::now() + worker_wait(&st, backoff_delay(st.backoff));
                }
                // Nothing runnable (not configured / disconnected / auth
                // required): go back to waiting without running a pass.
                drop(st);
                continue;
            };
            // Publish cancellation and activation in one control-state
            // transition so disconnect/stop always cancels this pass token.
            let pass_cancel = CancelToken::default();
            st.pass_cancel = pass_cancel.clone();
            st.pass_in_flight = true;
            st.active_action = Some(action);
            (action, pass_cancel)
        };

        // Status subscribers must observe the active pass before its first
        // potentially blocking provider call.
        hub.dispatch();
        // The pass runs network calls strictly outside the ctrl lock and
        // outside any SQLite lock.
        let mut outcome = run_pass(&store, provider.as_ref(), &pass_cancel, action, &hub);
        let mut more_claimable_mutations = false;
        if action == PassAction::Mutations && matches!(&outcome, PassOutcome::Complete) {
            match store.claimable_operation_count() {
                Ok(count) => more_claimable_mutations = count > 0,
                Err(error) => outcome = PassOutcome::Halt(error),
            }
            #[cfg(test)]
            let callback = ctrl
                .after_mutation_count
                .lock()
                .expect("test mutation-count hook poisoned")
                .take();
            #[cfg(test)]
            if let Some(callback) = callback {
                callback(more_claimable_mutations);
            }
        }

        let mut halted = false;
        {
            let mut st = ctrl.state.lock().expect("gmail ctrl poisoned");
            st.pass_in_flight = false;
            st.active_action = None;
            if action == PassAction::MutationUpgrade {
                st.upgrade_in_flight = false;
            }
            let reschedule = !matches!(outcome, PassOutcome::Idle | PassOutcome::Cancelled);
            if st.halted {
                halted = true;
            } else {
                match outcome {
                    PassOutcome::Complete => {
                        st.error = None;
                        st.backoff = 0;
                        if action.is_auth() || st.connection == ConnectionState::Authenticating {
                            st.connection = ConnectionState::Connected;
                        }
                        if action.is_auth()
                            || action == PassAction::Sync
                            || action == PassAction::MutationUpgrade
                        {
                            st.operations_requested = true;
                        } else if action == PassAction::Mutations {
                            // Preserve acceptances published after the count above.
                            st.operations_requested |= more_claimable_mutations;
                        }
                    }
                    PassOutcome::Idle => {}
                    PassOutcome::AuthError { error } => {
                        st.error = Some(error.clone());
                        st.backoff = st.backoff.saturating_add(1);
                        match action {
                            PassAction::Auth(AuthKind::Connect) => {
                                st.auth_auto_retry = false;
                                st.connection = auth_failure_connection(&error);
                            }
                            PassAction::Auth(AuthKind::Restore) => {
                                if is_retryable_network(&error) {
                                    // Stay `authenticating`; retry on the next
                                    // backoff tick until the account is known.
                                    st.auth_auto_retry = true;
                                } else {
                                    st.auth_auto_retry = false;
                                    st.connection = auth_failure_connection(&error);
                                }
                            }
                            PassAction::Sync
                            | PassAction::MutationUpgrade
                            | PassAction::Mutations => {}
                        }
                    }
                    PassOutcome::SyncError(error) => {
                        st.error = Some(error.clone());
                        st.backoff = st.backoff.saturating_add(1);
                        if is_auth_failure(&error) && action != PassAction::MutationUpgrade {
                            st.connection = ConnectionState::AuthRequired;
                        } else if action.is_auth() {
                            // Auth succeeded earlier in this pass; the failure is
                            // a sync problem, not a connection problem.
                            st.connection = ConnectionState::Connected;
                        }
                    }
                    PassOutcome::Halt(error) => {
                        st.error = Some(error);
                        st.halted = true;
                        cancel_independent_reads(&mut st);
                        halted = true;
                    }
                    PassOutcome::Cancelled => {
                        // Disconnect owns the state; ordinary upgrade cancellation
                        // resolves only that grant attempt without touching sync.
                        if action == PassAction::MutationUpgrade && !st.disconnecting {
                            st.error = None;
                        }
                    }
                }
            }
            if reschedule {
                sync_deadline = Instant::now() + worker_wait(&st, backoff_delay(st.backoff));
            }
            ctrl.wake.notify_all();
        }
        hub.dispatch();
        if halted {
            return;
        }
    }
}

/// Process local deadlines from the serial worker. A conditional reminder is
/// decided only after a complete fresh thread read; an error or partial thread
/// stays pending and remains visible through its due marker.
fn process_due_reminders(
    store: &GmailStore,
    provider: &dyn GmailProvider,
    ctrl: &Arc<Ctrl>,
    hub: &GmailHub,
) -> Result<(), MailError> {
    let due = store.due_reminders()?;
    for (reminder, baseline) in due {
        let replied = if reminder.condition == crate::reminders::ReminderCondition::Regardless {
            false
        } else {

        } else {
            let connected = {
                let state = ctrl.state.lock().map_err(storage_err())?;
                state.connection == ConnectionState::Connected
                    && !state.disconnecting
                    && !state.stop
                    && !state.halted
            };
            if !connected {
                continue;
            }
            let account = match store.account() {
                Ok(Some(account)) if account.account_id == reminder.conversation.account_id => {
                    account
                }
                Err(error) => return Err(error),
                _ => continue,
            };
            let generation = store.generation()?;
            let observation = store.observation_revision()?;
            let cancel = CancelToken::default();
            {
                let mut st = ctrl.state.lock().map_err(storage_err())?;
                if st.stop || st.halted || st.disconnecting {
                    continue;
                }
                st.reminder_read = Some(cancel.clone());
            }
            let thread = match provider.get_thread_for_account(
                &account.account_id,
                &reminder.conversation.conversation_id,
                &cancel,
            ) {
                Ok(Some(thread)) => thread,
                Err(error) => {
                    clear_reminder_read(ctrl);
                    if error == MailError::StorageUnavailable {
                        return Err(error);
                    }
                    continue;
                }
                _ => {
                    clear_reminder_read(ctrl);
                    continue;
                }
            };
            clear_reminder_read(ctrl);
            if thread.conversation.conversation_ref != reminder.conversation {
                continue;
            }
            let Some(ids) = thread.message_ids.as_ref() else {
                continue;
            };
            if thread.conversation.context_complete != Some(true) {
                continue;
            }
            let senders: HashMap<String, String> = thread
                .conversation
                .messages
                .iter()
                .map(|message| (message.id.clone(), message.from.mailbox.clone()))
                .collect();
            if ids.iter().any(|id| !senders.contains_key(id))
                || senders.keys().any(|id| !ids.contains(id))
            {
                continue;
            }
            let mut has_reply = false;
            let mut complete = true;
            for id in ids.iter().filter(|id| !baseline.contains(id)) {
                match senders.get(id) {
                    Some(sender) if !sender.eq_ignore_ascii_case(&account.email_address) => {
                        has_reply = true
                    }
                    Some(_) => {}
                    None => {
                        complete = false;
                        break;
                    }
                }
            }
            if !complete {
                continue;
            }
            let st = ctrl.state.lock().map_err(storage_err())?;
            if st.stop || st.halted || st.disconnecting {
                continue;
            }
            let changed = store.finish_due_reminder_with_thread(
                &reminder,
                generation,
                observation,
                has_reply,
                Some(&thread),
            )?;
            drop(st);
            if changed {
                hub.dispatch();
            }
            continue;
        };
        let generation = store.generation()?;
        let observation = store.observation_revision()?;
        let st = ctrl.state.lock().map_err(storage_err())?;
        if st.stop || st.halted || st.disconnecting {
            continue;
        }
        let changed = store.finish_due_reminder(&reminder, generation, observation, replied)?;
        drop(st);
        if changed {
            hub.dispatch();
        }
    }
    Ok(())
}

fn clear_reminder_read(ctrl: &Ctrl) {
    if let Ok(mut st) = ctrl.state.lock() {
        st.reminder_read = None;
        ctrl.wake.notify_all();
    }
}

fn run_pass(
    store: &GmailStore,
    provider: &dyn GmailProvider,
    cancel: &CancelToken,
    action: PassAction,
    hub: &GmailHub,
) -> PassOutcome {
    let generation = match store.generation() {
        Ok(generation) => generation,
        Err(error) => return PassOutcome::Halt(error),
    };
    if action == PassAction::MutationUpgrade {
        let account = match store.account() {
            Ok(Some(account)) => account,
            Ok(None) => return PassOutcome::SyncError(MailError::AuthRequired),
            Err(error) => return PassOutcome::Halt(error),
        };
        return match provider.enable_mutations(cancel) {
            Ok(profile) if profile.account_id != account.account_id => {
                PassOutcome::SyncError(MailError::InvalidRequest {
                    field: "accountId".to_string(),
                })
            }
            Ok(_) => match provider.mutation_access() {
                Ok(true) => PassOutcome::Complete,
                Ok(false) => PassOutcome::SyncError(MailError::PermissionRequired),
                Err(error) => PassOutcome::SyncError(error),
            },
            Err(MailError::AuthCancelled) if cancel.is_cancelled() => PassOutcome::Cancelled,
            Err(error) => PassOutcome::SyncError(error),
        };
    }
    if action == PassAction::Mutations {
        return match crate::gmail::operations::run_one(store, provider, cancel) {
            Ok(true) => PassOutcome::Complete,
            Ok(false) => PassOutcome::Idle,
            Err(MailError::StorageUnavailable) => PassOutcome::Halt(MailError::StorageUnavailable),
            Err(_error) if cancel.is_cancelled() => PassOutcome::Cancelled,
            Err(error) => PassOutcome::SyncError(error),
        };
    }
    if let PassAction::Auth(kind) = action {
        let attempted = match kind {
            AuthKind::Connect => provider.connect(cancel),
            AuthKind::Restore => provider.profile(cancel),
        };
        let profile = match attempted {
            Ok(profile) => profile,
            Err(error) => return PassOutcome::AuthError { error },
        };
        match store.begin_account(&profile, generation) {
            Ok(Commit::Applied) => {}
            Ok(Commit::Discarded) => return PassOutcome::Cancelled,
            // Account identity switching without disconnect fails closed as a
            // typed, visible auth error; the worker stays alive.
            Err(MailError::InvalidRequest { field }) if field == "accountId" => {
                return PassOutcome::AuthError {
                    error: MailError::InvalidRequest { field },
                };
            }
            Err(error) => return PassOutcome::Halt(error),
        }
    }
    match store.has_account() {
        Ok(true) => {}
        Ok(false) => return PassOutcome::Idle,
        Err(error) => return PassOutcome::Halt(error),
    }
    // Discovery first, then history catch-up from the pinned baseline; an
    // expired cursor restarts bounded discovery with reconciliation.
    let mut rediscovery_restarts = 0u32;
    loop {
        match run_discovery(store, provider, cancel, generation, hub) {
            StageOutcome::Complete => {}
            StageOutcome::ExpiredRestart => {
                return match store.schedule_unknown_reconciliation() {
                    Ok(()) => PassOutcome::Complete,
                    Err(error) => PassOutcome::Halt(error),
                };
            }
            StageOutcome::SyncError(error) => return PassOutcome::SyncError(error),
            StageOutcome::Halt(error) => return PassOutcome::Halt(error),
            StageOutcome::Cancelled => return PassOutcome::Cancelled,
        }
        match run_history(store, provider, cancel, generation, hub) {
            StageOutcome::Complete => {
                return match store.schedule_unknown_reconciliation() {
                    Ok(()) => PassOutcome::Complete,
                    Err(error) => PassOutcome::Halt(error),
                };
            }
            StageOutcome::ExpiredRestart => {
                rediscovery_restarts += 1;
                if rediscovery_restarts > MAX_REDISCOVERY_RESTARTS {
                    return PassOutcome::SyncError(MailError::InvalidProviderResponse);
                }
                // Loop back through discovery, which is Running again.
            }
            StageOutcome::SyncError(error) => return PassOutcome::SyncError(error),
            StageOutcome::Halt(error) => return PassOutcome::Halt(error),
            StageOutcome::Cancelled => return PassOutcome::Cancelled,
        }
    }
}

fn run_discovery(
    store: &GmailStore,
    provider: &dyn GmailProvider,
    cancel: &CancelToken,
    generation: u64,
    hub: &GmailHub,
) -> StageOutcome {
    let mut pages = 0usize;
    let mut requested_tokens = HashSet::new();
    loop {
        if pages >= MAX_PAGES_PER_STAGE {
            return StageOutcome::SyncError(MailError::InvalidProviderResponse);
        }
        if cancel.is_cancelled() {
            return StageOutcome::Cancelled;
        }
        let incoming_token = match store.discovery() {
            Ok(DiscoveryProgress::Done) => return StageOutcome::Complete,
            Ok(DiscoveryProgress::Pending) => None,
            Ok(DiscoveryProgress::Running { page_token }) => page_token,
            Err(error) => return StageOutcome::Halt(error),
        };
        if !requested_tokens.insert(incoming_token.clone()) {
            return StageOutcome::SyncError(MailError::InvalidProviderResponse);
        }
        let page = match provider.list_inbox(incoming_token.as_deref(), cancel) {
            Ok(page) => page,
            Err(error) => return StageOutcome::SyncError(error),
        };
        pages += 1;
        if page.thread_ids.len() > MAX_DISCOVERY_IDS_PER_PAGE
            || page
                .next_page_token
                .as_ref()
                .is_some_and(|next| requested_tokens.contains(&Some(next.clone())))
        {
            return StageOutcome::SyncError(MailError::InvalidProviderResponse);
        }
        // Dedup repeated ids across and within pages; never re-fetch threads
        // already committed by this run; cap the run's discovered count.
        let seen = match store.seen_ids() {
            Ok(seen) => seen,
            Err(error) => return StageOutcome::Halt(error),
        };
        let seen_set: HashSet<&String> = seen.iter().collect();
        let mut fetched: Vec<ThreadFetch> = Vec::new();
        let mut retained_bytes = 0usize;
        let mut page_dedup: HashSet<&String> = HashSet::new();
        let mut discovered = 0usize;
        let mut capped = false;
        for id in &page.thread_ids {
            if !page_dedup.insert(id) || seen_set.contains(id) {
                continue;
            }
            if seen.len() + discovered >= DISCOVERY_CAP {
                capped = true;
                break;
            }
            match provider.get_thread(id, cancel) {
                Ok(Some(thread)) => {
                    if thread.conversation.conversation_ref.conversation_id != *id {
                        return StageOutcome::SyncError(MailError::InvalidProviderResponse);
                    }
                    if !include_retained_bytes(&mut retained_bytes, retained_thread_bytes(&thread))
                    {
                        return StageOutcome::SyncError(MailError::InvalidProviderResponse);
                    }
                    fetched.push(ThreadFetch::Cached(Box::new(thread)));
                    discovered += 1;
                }
                Ok(None) => {
                    let missing_bytes = std::mem::size_of::<ThreadFetch>() + id.capacity();
                    if !include_retained_bytes(&mut retained_bytes, missing_bytes) {
                        return StageOutcome::SyncError(MailError::InvalidProviderResponse);
                    }
                    fetched.push(ThreadFetch::Missing(id.clone()));
                }
                Err(error) => {
                    // Preserve the threads already fetched from this page:
                    // the page token is NOT advanced, so a rate-limit retry
                    // or restart re-lists this page and skips committed
                    // threads via the durable seen set instead of refetching
                    // them. A generation race (disconnect) discards the
                    // partial write like any stale result.
                    match store.apply_discovery_page(
                        &fetched,
                        incoming_token.as_deref(),
                        false,
                        false,
                        generation,
                    ) {
                        Ok(Commit::Applied) => return StageOutcome::SyncError(error),
                        Ok(Commit::Discarded) => return StageOutcome::Cancelled,
                        Err(commit_error) => return StageOutcome::Halt(commit_error),
                    }
                }
            }
        }
        let done = page.next_page_token.is_none() || capped;
        match store.apply_discovery_page(
            &fetched,
            page.next_page_token.as_deref(),
            done,
            capped,
            generation,
        ) {
            Ok(Commit::Applied) => {}
            Ok(Commit::Discarded) => return StageOutcome::Cancelled,
            Err(error) => return StageOutcome::Halt(error),
        }
        hub.dispatch();
        if done {
            return StageOutcome::Complete;
        }
    }
}

fn run_history(
    store: &GmailStore,
    provider: &dyn GmailProvider,
    cancel: &CancelToken,
    generation: u64,
    hub: &GmailHub,
) -> StageOutcome {
    let mut pages = 0usize;
    let mut requested_tokens = HashSet::new();
    loop {
        if pages >= MAX_PAGES_PER_STAGE {
            return StageOutcome::SyncError(MailError::InvalidProviderResponse);
        }
        if cancel.is_cancelled() {
            return StageOutcome::Cancelled;
        }
        let (batch_start, incoming_token) = match store.history() {
            Ok(HistoryProgress::Idle {
                cursor: Some(cursor),
            }) => (cursor, None),
            Ok(HistoryProgress::Idle { cursor: None }) => return StageOutcome::Complete,
            Ok(HistoryProgress::Resuming {
                batch_start,
                page_token,
            }) => (batch_start, Some(page_token)),
            Err(error) => return StageOutcome::Halt(error),
        };
        let incoming_token = incoming_token.flatten();
        if !requested_tokens.insert(incoming_token.clone()) {
            return StageOutcome::SyncError(MailError::InvalidProviderResponse);
        }
        let page = match provider.history(&batch_start, incoming_token.as_deref(), cancel) {
            Ok(page) => page,
            Err(crate::gmail::types::GmailHistoryError::Expired) => {
                // Cursor expired: bounded rediscovery from a fresh baseline,
                // never a silent skip of the expired window.
                let profile = match provider.profile(cancel) {
                    Ok(profile) => profile,
                    Err(error) => return StageOutcome::SyncError(error),
                };
                match store.begin_rediscovery(&profile.history_id, generation) {
                    Ok(Commit::Applied) => return StageOutcome::ExpiredRestart,
                    Ok(Commit::Discarded) => return StageOutcome::Cancelled,
                    Err(error) => return StageOutcome::Halt(error),
                }
            }
            Err(crate::gmail::types::GmailHistoryError::Mail(error)) => {
                return StageOutcome::SyncError(error)
            }
        };
        pages += 1;
        if page.changed_thread_ids.len() > MAX_HISTORY_IDS_PER_PAGE
            || page
                .next_page_token
                .as_ref()
                .is_some_and(|next| requested_tokens.contains(&Some(next.clone())))
        {
            return StageOutcome::SyncError(MailError::InvalidProviderResponse);
        }
        let fetched = match fetch_changed_threads(provider, &page.changed_thread_ids, cancel) {
            Ok(fetched) => fetched,
            Err(error) => return StageOutcome::SyncError(error),
        };
        match store.apply_history_page(&page, &fetched, &batch_start, generation) {
            Ok(Commit::Applied) => {}
            Ok(Commit::Discarded) => return StageOutcome::Cancelled,
            Err(error) => return StageOutcome::Halt(error),
        }
        hub.dispatch();
        if page.next_page_token.is_none() {
            // All pages of this batch applied; the cursor advanced inside the
            // final transaction.
            return StageOutcome::Complete;
        }
    }
}

/// Fetches changed threads with per-page dedup; `None` responses become
/// removals. Pathological provider data (mismatched ids) fails typed.
fn fetch_changed_threads(
    provider: &dyn GmailProvider,
    changed_thread_ids: &[String],
    cancel: &CancelToken,
) -> Result<Vec<ThreadFetch>, MailError> {
    let mut fetched = Vec::new();
    let mut retained_bytes = 0usize;
    let mut page_dedup: HashSet<&String> = HashSet::new();
    for id in changed_thread_ids {
        if !page_dedup.insert(id) {
            continue;
        }
        match provider.get_thread(id, cancel)? {
            Some(thread) => {
                if thread.conversation.conversation_ref.conversation_id != *id {
                    return Err(MailError::InvalidProviderResponse);
                }
                if !include_retained_bytes(&mut retained_bytes, retained_thread_bytes(&thread)) {
                    return Err(MailError::InvalidProviderResponse);
                }
                fetched.push(ThreadFetch::Cached(Box::new(thread)));
            }
            None => {
                let missing_bytes = std::mem::size_of::<ThreadFetch>() + id.capacity();
                if !include_retained_bytes(&mut retained_bytes, missing_bytes) {
                    return Err(MailError::InvalidProviderResponse);
                }
                fetched.push(ThreadFetch::Missing(id.clone()));
            }
        }
    }
    Ok(fetched)
}

fn include_retained_bytes(total: &mut usize, additional: usize) -> bool {
    let Some(next) = total.checked_add(additional) else {
        return false;
    };
    if next > MAX_RETAINED_THREAD_BYTES_PER_PAGE {
        return false;
    }
    *total = next;
    true
}

/// Conservative estimate of heap retained by one DTO, including collection
/// capacities and string allocations rather than only body text lengths.

//! Concrete single-operation executor for durable Gmail mailbox setters.
use crate::dto::{MailboxOperationKind, OperationStatus};
use crate::error::MailError;
use crate::gmail::store::{GmailStore, OperationRecord};
use crate::gmail::types::{GmailProvider, GmailThread};
use crate::CancelToken;

/// Runs at most one queued setter or one uncertain-outcome reconciliation.
/// The caller is the existing serial Gmail worker; no storage lock is held
/// during profile, reconciliation, or setter provider calls.
pub(crate) fn run_one(
    store: &GmailStore,
    provider: &dyn GmailProvider,
    cancel: &CancelToken,
) -> Result<bool, MailError> {
    let Some(record) = store.claim_next_operation()? else {
        return Ok(false);
    };
    if cancel.is_cancelled() {
        // A disconnect clears the durable rows after the worker reaches its
        // admission barrier. A plain shutdown leaves applying for restart
        // recovery, where migration converts it to outcome_unknown.
        return Ok(true);
    }

    let uncertain = record.status == OperationStatus::OutcomeUnknown;
    if !uncertain {
        require_mutation_access(store, provider, &record)?;
    }
    let profile = match provider.profile(cancel) {
        Ok(profile) => profile,
        Err(error) => {
            if uncertain {
                store.defer_unknown_operation(&record, &error)?;
            } else {
                store.requeue_operation(&record, &error)?;
            }
            return Err(error);
        }
    };
    if profile.account_id != record.account_id {
        let error = MailError::InvalidRequest {
            field: "accountId".to_string(),
        };
        if uncertain {
            store.defer_unknown_operation(&record, &error)?;
        } else {
            store.fail_operation(&record, error.clone())?;
        }
        return Err(error);
    }

    if uncertain {
        return reconcile(store, provider, cancel, &record);
    }

    // The grant may have been revoked between enqueue and dispatch. Check the
    // local verified capability again immediately before the setter.
    require_mutation_access(store, provider, &record)?;
    if cancel.is_cancelled() {
        return Ok(true);
    }
    let result = match record.kind {
        MailboxOperationKind::Star => {
            provider.apply_star(&record.message_ids, record.value, cancel)
        }
        MailboxOperationKind::Archive => {
            provider.apply_archive(&record.message_ids, record.value, cancel)
        }
        MailboxOperationKind::Read => {
            provider.apply_read(&record.message_ids, record.value, cancel)
        }
    };
    match result {
        Ok(()) => store.confirm_operation(&record)?,
        Err(MailError::OutcomeUnknown | MailError::AuthCancelled) => {
            store.unknown_operation(&record)?;
            if !cancel.is_cancelled() {
                return reconcile(store, provider, cancel, &record);
            }
        }
        Err(error @ MailError::StorageUnavailable) => return Err(error),
        // The production setter uses these two errors only while refreshing a
        // token before batchModify; post-dispatch uncertainty is OutcomeUnknown.
        Err(
            error @ (MailError::NetworkUnavailable
            | MailError::ProviderUnavailable
            | MailError::InvalidProviderResponse
            | MailError::RateLimited
            | MailError::AuthRequired
            | MailError::PermissionRequired
            | MailError::SecretsUnavailable),
        ) => {
            store.requeue_operation(&record, &error)?;
            return Err(error);
        }
        Err(error) => {
            store.fail_operation(&record, error.clone())?;
            return Err(error);
        }
    }
    Ok(true)
}

fn reconcile(
    store: &GmailStore,
    provider: &dyn GmailProvider,
    cancel: &CancelToken,
    record: &OperationRecord,
) -> Result<bool, MailError> {
    let fetched = match provider.get_thread(&record.conversation_id, cancel) {
        Ok(Some(thread)) => thread,
        Ok(None) => {
            store.reconciled_unknown_operation(record)?;
            return Ok(true);
        }
        Err(error) => {
            store.defer_unknown_operation(record, &error)?;
            return Err(error);
        }
    };
    if fetched.conversation.conversation_ref.account_id != record.account_id
        || fetched.conversation.conversation_ref.conversation_id != record.conversation_id
    {
        store.reconciled_unknown_operation(record)?;
        return Ok(true);
    }
    let all_ids = observed_ids(&fetched);
    if !record.message_ids.iter().all(|id| all_ids.contains(id)) {
        store.reconcile_operation(record, &fetched, false)?;
        return Ok(true);
    }
    let matches_all = record.message_ids.iter().all(|id| match record.kind {
        MailboxOperationKind::Star => {
            fetched.star_facts.as_ref().and_then(|facts| facts.get(id)) == Some(&record.value)
        }
        MailboxOperationKind::Archive => fetched.inbox_message_ids.contains(id) != record.value,
        MailboxOperationKind::Read => fetched
            .unread_message_ids
            .as_ref()
            .is_some_and(|ids| ids.contains(id) != record.value),
    });
    store.reconcile_operation(record, &fetched, matches_all)?;
    Ok(true)
}

fn require_mutation_access(
    store: &GmailStore,
    provider: &dyn GmailProvider,
    record: &OperationRecord,
) -> Result<(), MailError> {
    match provider.mutation_access() {
        Ok(true) => Ok(()),
        Ok(false) => {
            store.requeue_operation(record, &MailError::PermissionRequired)?;
            Err(MailError::PermissionRequired)
        }
        Err(error) => {
            if error != MailError::StorageUnavailable {
                store.requeue_operation(record, &error)?;
            }
            Err(error)
        }
    }
}

fn observed_ids(thread: &GmailThread) -> Vec<String> {
    if let Some(ids) = &thread.message_ids {
        return ids.clone();
    }
    let mut ids = thread.inbox_message_ids.clone();
    for message in &thread.conversation.messages {
        if !ids.contains(&message.id) {
            ids.push(message.id.clone());
        }
    }
    ids
}
//! Shared contract scenarios (ticket 17): the Rust half.
//!
//! Executes every file under `tests/fixtures/contract-scenarios/` against the
//! Rust backends and compares each step's observable result with the file's
//! expectations. The browser fake runs the SAME files from
//! `tests/browser-fake/contract-scenarios.test.ts`; the format is documented
//! in docs/development.md ("Contract scenarios").
//!
//! Backends under test (a parameter, see [`Backend`]):
//! * `gmail`   — `GmailCore` + the shared scripted `mail_core::testing` fake provider;
//! * `fixture` — the archive-only fixture `MailCore` + `FakeArchiveProvider`.
//!
//! Time is each backend's `FakeClock`; nothing waits on wall-clock time. The
//! only polling is the shared bounded `until` used to observe an expected
//! state of the asynchronous worker.

use std::collections::{BTreeMap, HashMap};
use std::path::PathBuf;
use std::sync::Arc;

use mail_core::clock::{utc, Clock, FakeClock};
use mail_core::dto::{RetryOperation, SetArchived, SetRead, UndoOperation};
use mail_core::error::MailError;
use mail_core::gmail::sync::GmailCore;
use mail_core::gmail::types::GmailThread;
use mail_core::groups::{
    GetOperationGroupRequest, ListOperationGroupsRequest, SetArchivedGroup, SetReadGroup,
    UndoOperationGroup,
};
use mail_core::stars::{SetStarred, SetStarredGroup};
use mail_core::testing::operations_fake::{ApplyPlan, FakeProvider};
use mail_core::testing::{open_core_with_clock, temp_profile, until};
use mail_core::{FakeArchiveProvider, MailCore};
use serde_json::{json, Value};

const CLOCK_START: &str = "2026-02-01T00:00:00Z";
const GMAIL_ACCOUNT: &str = "acct-contract";

/// Named, VISIBLE divergences: `(scenario, profile, why)`. The runner still
/// executes these and requires them to FAIL; when the divergence is fixed the
/// run fails until the entry is removed, so nothing is silently skipped.
const KNOWN_DIVERGENCES: &[(&str, &str, &str)] = &[(
    "group-member-failure-does-not-stop-siblings",
    "gmail",
    "KD-1: after a definite provider failure the Gmail worker ends its pass in sync-error backoff \
     (gmail/operations.rs run_one returns Err, sync.rs PassOutcome::SyncError), so queued siblings \
     stay `queued` until the next retry tick; the fixture worker keeps draining serially. \
     docs/ux-05 §4.1 only says children run serially and failures do not roll back siblings.",
)];

// ------------------------------------------------------------------ backends

trait Backend {
    fn account_id(&self) -> String;
    fn execute(&self, command: &str, args: Value) -> Result<Value, MailError>;
    fn snapshot(&self) -> Value;
    fn advance(&self, seconds: i64);
    fn provider(&self, mode: &str) -> Result<(), String>;
    /// Called after a step's expectations settled (resets one-shot arming).
    fn after_step(&self, was_command: bool);
}

fn to_value<T: serde::Serialize>(result: Result<T, MailError>) -> Result<Value, MailError> {
    result.map(|value| serde_json::to_value(value).expect("serialize DTO"))
}

fn args_as<T: serde::de::DeserializeOwned>(args: Value) -> T {
    serde_json::from_value(args).expect("scenario args deserialize into the contract DTO")
}

struct GmailBackend {
    core: GmailCore,
    provider: Arc<FakeProvider>,
    clock: Arc<FakeClock>,
    armed_reject: std::sync::atomic::AtomicBool,
    _dir: tempfile::TempDir,
}

impl GmailBackend {
    fn open(mailbox: &Value) -> Self {
        let dir = temp_profile("contract-gmail");
        let clock = Arc::new(FakeClock::new(utc(CLOCK_START)));
        let threads = mailbox["conversations"]
            .as_array()
            .expect("mailbox conversations")
            .iter()
            .map(gmail_thread)
            .collect::<Vec<_>>();
        let provider = FakeProvider::with_threads(threads);
        let core = open_core_with_clock(dir.path(), &provider, &clock);
        assert!(
            until(|| core.account_status().is_ok_and(|status| {
                status.connection == mail_core::gmail::types::ConnectionState::Connected
                    && status.sync.initial_sync_complete
            })),
            "gmail core did not finish its first sync"
        );
        core.wait_for_test_idle(mail_core::testing::TIMEOUT)
            .expect("idle after first sync");
        Self {
            core,
            provider,
            clock,
            armed_reject: false.into(),
            _dir: dir,
        }
    }
}

fn gmail_thread(conversation: &Value) -> GmailThread {
    let id = conversation["id"].as_str().expect("conversation id");
    let messages_json = conversation["messages"].as_array().expect("messages");
    let messages: Vec<_> = messages_json
        .iter()
        .map(|m| {
            mail_core::testing::message(
                m["id"].as_str().unwrap(),
                "sender@example.test",
                m["sentAt"].as_str().unwrap(),
                "synthetic body",
            )
        })
        .collect();
    let flagged = |key: &str| -> Vec<String> {
        messages_json
            .iter()
            .filter(|m| m[key].as_bool() == Some(true))
            .map(|m| m["id"].as_str().unwrap().to_string())
            .collect()
    };
    let inbox = flagged("inInbox");
    let inbox_refs: Vec<&str> = inbox.iter().map(String::as_str).collect();
    let newest = messages
        .iter()
        .max_by(|a, b| (&a.sent_at, &a.id).cmp(&(&b.sent_at, &b.id)))
        .map(|m| m.from.clone());
    let mut thread = mail_core::testing::thread(
        GMAIL_ACCOUNT,
        id,
        messages,

        messages,
        &inbox_refs,
        Some(flagged("unread")),
        "history-1",
    );
    thread.newest_sender = newest;
    thread.conversation.subject = format!("subject {id}");
    // Star facts are known only for messages that declare `starred`.
    let known: std::collections::HashMap<String, bool> = messages_json
        .iter()
        .filter_map(|m| Some((m["id"].as_str()?.to_string(), m["starred"].as_bool()?)))
        .collect();
    if !known.is_empty() {
        thread.star_facts = Some(known);
    }
    thread
}

impl Backend for GmailBackend {
    fn account_id(&self) -> String {
        GMAIL_ACCOUNT.to_string()
    }
    fn execute(&self, command: &str, args: Value) -> Result<Value, MailError> {
        let core = &self.core;
        match command {
            "setArchived" => to_value(core.set_archived(&args_as::<SetArchived>(args))),
            "setRead" => to_value(core.set_read(&args_as::<SetRead>(args))),
            "setStarred" => to_value(core.set_starred(&args_as::<SetStarred>(args))),
            "retryOperation" => to_value(core.retry_operation(&args_as::<RetryOperation>(args))),
            "undoOperation" => to_value(core.undo_operation(&args_as::<UndoOperation>(args))),
            "setArchivedGroup" => {
                to_value(core.set_archived_group(&args_as::<SetArchivedGroup>(args)))
            }
            "setReadGroup" => to_value(core.set_read_group(&args_as::<SetReadGroup>(args))),
            "setStarredGroup" => {
                to_value(core.set_starred_group(&args_as::<SetStarredGroup>(args)))
            }
            "getOperationGroup" => {
                to_value(core.get_operation_group(&args_as::<GetOperationGroupRequest>(args)))
            }
            "listOperationGroups" => {
                to_value(core.list_operation_groups(&args_as::<ListOperationGroupsRequest>(args)))
            }
            "undoOperationGroup" => {
                to_value(core.undo_operation_group(&args_as::<UndoOperationGroup>(args)))
            }
            other => panic!("unknown contract command {other}"),
        }
    }
    fn snapshot(&self) -> Value {
        serde_json::to_value(self.core.list_conversations().expect("list_conversations"))
            .expect("serialize snapshot")
    }
    fn advance(&self, seconds: i64) {
        self.clock.advance_seconds(seconds);
    }
    fn provider(&self, mode: &str) -> Result<(), String> {
        match mode {
            "hold_queued" => self
                .core
                .pause_test_operations(mail_core::testing::TIMEOUT)
                .map_err(|e| format!("pause: {e:?}")),
            "hold_applying" => {
                self.provider.set_apply_plan(ApplyPlan::BlockThenSuccess);
                Ok(())
            }
            "reject_next" => {
                self.provider
                    .set_apply_plan(ApplyPlan::Error(MailError::ProviderRejected));
                self.armed_reject
                    .store(true, std::sync::atomic::Ordering::SeqCst);
                Ok(())
            }
            "release" => {
                self.provider.set_apply_plan(ApplyPlan::Success);
                self.provider.release_apply();
                self.core.release_test_operations();
                Ok(())
            }
            other => Err(format!("unknown provider mode {other}")),
        }
    }
    fn after_step(&self, was_command: bool) {
        if was_command
            && self
                .armed_reject
                .swap(false, std::sync::atomic::Ordering::SeqCst)
        {
            self.provider.set_apply_plan(ApplyPlan::Success);
        }
    }
}

/// The fixture backend mirrors the native shell's `Backend::Fixture` dispatch
/// (src-tauri/src/main.rs): archive, undo and archive groups are forwarded to
/// `MailCore`; every other mailbox command is rejected exactly as the shell
/// rejects it today. The worker starts lazily so a scenario can hold work
/// queued by declaring `hold_queued` first.
struct FixtureBackend {
    core: MailCore,
    provider: Arc<FakeArchiveProvider>,
    clock: Arc<FakeClock>,
    state: std::sync::Mutex<FixtureState>,
    _dir: tempfile::TempDir,
}

#[derive(Default)]
struct FixtureState {
    worker_started: bool,
    hold_queued: bool,
}

impl FixtureBackend {
    fn open(mailbox: &Value) -> Self {
        let dir = temp_profile("contract-fixture");
        let clock = Arc::new(FakeClock::new(utc(CLOCK_START)));
        let core = MailCore::open_with_clock(dir.path(), Arc::clone(&clock) as Arc<dyn Clock>)
            .expect("open fixture core");
        let backend = Self {
            core,
            provider: Arc::new(FakeArchiveProvider::new()),
            clock,
            state: Default::default(),
            _dir: dir,
        };
        backend.check_mailbox_matches_seed(mailbox);
        backend
    }

    /// The fixture's data is its fixed seed. A scenario may run here only if
    /// its declared mailbox is a faithful subset of that seed.
    fn check_mailbox_matches_seed(&self, mailbox: &Value) {
        let snapshot = serde_json::to_value(self.core.list_conversations().unwrap()).unwrap();
        let declared: Vec<&Value> = mailbox["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .collect();
        let in_inbox_ids: Vec<String> = snapshot["conversations"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| c["ref"]["conversationId"].as_str().unwrap().to_string())
            .collect();
        let mut expected_inbox: Vec<(&str, &str)> = Vec::new();
        for conv in &declared {
            let id = conv["id"].as_str().unwrap();
            let messages = conv["messages"].as_array().unwrap();
            let any_inbox = messages.iter().any(|m| m["inInbox"] == json!(true));
            assert_eq!(
                in_inbox_ids.iter().any(|x| x == id),
                any_inbox,
                "mailbox conversation {id} disagrees with the fixture seed about Inbox membership"
            );
            if any_inbox {
                let last = messages
                    .iter()
                    .map(|m| m["sentAt"].as_str().unwrap())
                    .max()
                    .unwrap();
                expected_inbox.push((id, last));
            }
        }
        expected_inbox.sort_by(|a, b| b.1.cmp(a.1));
        let declared_ids: Vec<&str> = declared.iter().map(|c| c["id"].as_str().unwrap()).collect();
        let actual_order: Vec<&String> = in_inbox_ids
            .iter()
            .filter(|id| declared_ids.contains(&id.as_str()))
            .collect();
        let expected_order: Vec<&str> = expected_inbox.iter().map(|e| e.0).collect();
        assert_eq!(
            actual_order.iter().map(|s| s.as_str()).collect::<Vec<_>>(),
            expected_order,
            "mailbox Inbox order disagrees with the fixture seed"
        );
    }

    fn ensure_worker(&self) {
        let mut state = self.state.lock().unwrap();
        if !state.worker_started && !state.hold_queued {
            self.core
                .start_worker(self.provider.clone())
                .expect("start fixture worker");
            state.worker_started = true;
        }
    }
}

impl Backend for FixtureBackend {
    fn account_id(&self) -> String {
        self.core.account_id().to_string()
    }
    fn execute(&self, command: &str, args: Value) -> Result<Value, MailError> {
        self.ensure_worker();
        let core = &self.core;
        let invalid_mode = || {
            Err(MailError::InvalidRequest {
                field: "mode".to_string(),
            })
        };
        match command {
            "setArchived" => to_value(core.set_archived(&args_as::<SetArchived>(args))),
            "undoOperation" => to_value(core.undo_operation(&args_as::<UndoOperation>(args))),
            "setArchivedGroup" => {
                to_value(core.set_archived_group(&args_as::<SetArchivedGroup>(args)))
            }
            "getOperationGroup" => {
                to_value(core.get_operation_group(&args_as::<GetOperationGroupRequest>(args)))
            }
            "listOperationGroups" => {
                to_value(core.list_operation_groups(&args_as::<ListOperationGroupsRequest>(args)))
            }
            "undoOperationGroup" => {
                to_value(core.undo_operation_group(&args_as::<UndoOperationGroup>(args)))
            }
            // Shell: Backend::Fixture => Err(ReadOnly)
            "setStarred" | "setStarredGroup" => Err(MailError::ReadOnly),
            // Shell: Backend::Fixture => Err(InvalidRequest { field: "mode" })
            "setRead" | "setReadGroup" | "retryOperation" => invalid_mode(),
            other => panic!("unknown contract command {other}"),
        }
    }
    fn snapshot(&self) -> Value {
        serde_json::to_value(self.core.list_conversations().expect("list_conversations"))
            .expect("serialize snapshot")
    }
    fn advance(&self, seconds: i64) {
        self.clock.advance_seconds(seconds);
    }
    fn provider(&self, mode: &str) -> Result<(), String> {
        match mode {
            "hold_queued" => {
                let mut state = self.state.lock().unwrap();
                if state.worker_started {
                    return Err("fixture can only hold queued work before its worker starts".into());
                }
                state.hold_queued = true;
                Ok(())
            }
            "hold_applying" => {
                self.ensure_worker();
                self.provider.set_paused(true);
                Ok(())
            }
            "reject_next" => {
                self.ensure_worker();
                self.provider.fail_next();
                Ok(())
            }
            "release" => {
                self.provider.set_paused(false);
                let mut state = self.state.lock().unwrap();
                state.hold_queued = false;
                drop(state);
                self.ensure_worker();
                Ok(())
            }
            other => Err(format!("unknown provider mode {other}")),
        }
    }
    fn after_step(&self, _was_command: bool) {}
}

// --------------------------------------------------------- symbols & matching

/// Symbolic ids: `$name` binds on first appearance in an expectation and must
/// then be equal everywhere; distinct names must bind distinct values.
#[derive(Clone, Default)]
struct Bindings {
    forward: HashMap<String, String>,
    reverse: HashMap<String, String>,
}

impl Bindings {
    fn bind(&mut self, name: &str, actual: &str) -> Result<(), String> {
        match self.forward.get(name) {
            Some(bound) if bound == actual => Ok(()),
            Some(bound) => Err(format!("${name} was {bound:?} but is now {actual:?}")),
            None => {
                if let Some(other) = self.reverse.get(actual) {
                    return Err(format!(
                        "${name} and ${other} are the same value {actual:?}"
                    ));
                }
                self.forward.insert(name.to_string(), actual.to_string());
                self.reverse.insert(actual.to_string(), name.to_string());
                Ok(())
            }
        }
    }
}

fn offset_seconds(iso: &str) -> Option<i64> {
    let start = utc(CLOCK_START);
    chrono::DateTime::parse_from_rfc3339(iso)
        .ok()
        .map(|t| (t.with_timezone(&chrono::Utc) - start).num_seconds())
}

/// Subset match: every key in `expected` must match; `null` also matches an
/// absent key; arrays match element-for-element and length-for-length.
fn matches(
    expected: &Value,
    actual: &Value,
    path: &str,
    bindings: &mut Bindings,
) -> Result<(), String> {
    match expected {
        Value::String(text) if text.starts_with('$') => {
            let Some(actual) = actual.as_str() else {
                return Err(format!(
                    "{path}: expected a string for {text}, got {actual}"
                ));
            };
            bindings
                .bind(&text[1..], actual)
                .map_err(|e| format!("{path}: {e}"))
        }
        Value::String(text) if text.starts_with("@+") => {
            let offset: i64 = text[2..].parse().expect("@+N offset");
            match actual.as_str().and_then(offset_seconds) {
                Some(actual_offset) if actual_offset == offset => Ok(()),
                other => Err(format!(
                    "{path}: expected clock offset +{offset}s, got {actual} ({other:?})"
                )),
            }
        }
        Value::Null => {
            if actual.is_null() {
                Ok(())
            } else {
                Err(format!("{path}: expected null/absent, got {actual}"))
            }
        }
        Value::Object(map) if map.contains_key("$each") || map.contains_key("$length") => {
            let Some(got) = actual.as_array() else {
                return Err(format!("{path}: expected an array, got {actual}"));
            };
            if let Some(length) = map.get("$length").and_then(Value::as_u64) {
                if got.len() as u64 != length {
                    return Err(format!(
                        "{path}: expected {length} items, got {}",
                        got.len()
                    ));
                }
            }
            if let Some(each) = map.get("$each") {
                for (index, have) in got.iter().enumerate() {
                    matches(each, have, &format!("{path}[{index}]"), bindings)?;
                }
            }
            Ok(())
        }
        Value::Object(map) => {
            if !actual.is_object() {
                return Err(format!("{path}: expected an object, got {actual}"));
            }
            for (key, want) in map {
                matches(
                    want,
                    actual.get(key).unwrap_or(&Value::Null),
                    &format!("{path}.{key}"),
                    bindings,
                )?;
            }
            Ok(())
        }
        Value::Array(items) => {
            let Some(got) = actual.as_array() else {
                return Err(format!("{path}: expected an array, got {actual}"));
            };
            if items.len() != got.len() {
                return Err(format!(
                    "{path}: expected {} items, got {}: {}",
                    items.len(),
                    got.len(),
                    short(actual)
                ));
            }
            for (index, (want, have)) in items.iter().zip(got).enumerate() {
                matches(want, have, &format!("{path}[{index}]"), bindings)?;
            }
            Ok(())
        }
        other => {
            if other == actual {
                Ok(())
            } else {
                Err(format!("{path}: expected {other}, got {actual}"))
            }
        }
    }
}

/// Replaces `$name` strings with their bound values (command arguments).
fn substitute(value: &Value, bindings: &Bindings) -> Value {
    match value {
        Value::String(text) if text.starts_with('$') => Value::String(
            bindings
                .forward
                .get(&text[1..])
                .unwrap_or_else(|| panic!("argument refers to unbound symbol {text}"))
                .clone(),
        ),
        Value::Array(items) => {
            Value::Array(items.iter().map(|v| substitute(v, bindings)).collect())
        }
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(k, v)| (k.clone(), substitute(v, bindings)))
                .collect(),
        ),
        other => other.clone(),
    }
}

/// Argument shorthand shared with the TypeScript runner (docs/development.md):
/// a string `conversation`/member is a ref in the backend's own account, an
/// object `{account, id}` names another account, `{generate: {prefix, count}}`
/// expands to `prefix + 1-based zero-padded(3) index`, and `accountId` defaults
/// to the backend's account.
fn normalize_args(command: &str, args: &Value, account: &str) -> Value {
    let mut args = args.clone();
    let object = args.as_object_mut().expect("args are an object");
    let reference = |value: &Value| -> Value {
        match value {
            Value::String(id) => json!({"accountId": account, "conversationId": id}),
            Value::Object(map) if map.contains_key("id") => json!({
                "accountId": map.get("account").and_then(Value::as_str).unwrap_or(account),
                "conversationId": map["id"],
            }),
            other => other.clone(),
        }
    };
    if let Some(conversation) = object.get("conversation").cloned() {
        object.insert("conversation".into(), reference(&conversation));
    }
    if let Some(members) = object.get("members").cloned() {
        let expanded: Vec<Value> = match &members {
            Value::Object(map) if map.contains_key("generate") => {
                let spec = &map["generate"];
                let prefix = spec["prefix"].as_str().unwrap();
                (1..=spec["count"].as_u64().unwrap())
                    .map(|i| Value::String(format!("{prefix}{i:03}")))
                    .collect()
            }
            Value::Array(items) => items.clone(),
            other => panic!("members must be an array or a generate spec, got {other}"),
        };
        object.insert(
            "members".into(),
            Value::Array(expanded.iter().map(reference).collect()),
        );
    }
    let group_command = matches!(
        command,
        "setArchivedGroup"
            | "setReadGroup"
            | "setStarredGroup"
            | "getOperationGroup"
            | "listOperationGroups"
    );
    if group_command && !object.contains_key("accountId") {
        object.insert("accountId".into(), Value::String(account.to_string()));
    }
    if command == "listOperationGroups" && !object.contains_key("cursor") {
        object.insert("cursor".into(), Value::Null);
    }
    args
}

/// `snapshot.inbox: [ids]` is shorthand for the matching `conversations` list.
fn expand_snapshot(want: &Value) -> Value {
    let mut want = want.clone();
    if let Some(inbox) = want.as_object_mut().and_then(|o| o.remove("inbox")) {
        let rows: Vec<Value> = inbox
            .as_array()
            .expect("inbox is an array of conversation ids")
            .iter()
            .map(|id| json!({"ref": {"conversationId": id}}))
            .collect();
        want["conversations"] = Value::Array(rows);
    }
    want
}

/// Restricts the Inbox listing to the scenario's declared conversations (the
/// fixture seed holds extra mail the scenario never mentions).
fn restrict_to_declared(mut snapshot: Value, declared: &[String]) -> Value {
    if let Some(rows) = snapshot["conversations"].as_array_mut() {
        rows.retain(|row| {
            row["ref"]["conversationId"]
                .as_str()
                .is_some_and(|id| declared.iter().any(|d| d == id))
        });
    }
    if let Some(rows) = snapshot["activity"].as_array_mut() {
        rows.retain(|row| {
            row["conversation"]["conversationId"]
                .as_str()
                .is_some_and(|id| declared.iter().any(|d| d == id))
        });
    }
    snapshot
}

