                "DELETE FROM gmail_inbox_membership WHERE account_id = ?1 AND message_id = ?2",
                params![account_id, message_id],
            )
            .map_err(storage_err())?;
            tx.execute(
                "DELETE FROM gmail_message_facts WHERE account_id = ?1 AND message_id = ?2",
                params![account_id, message_id],
            )
            .map_err(storage_err())?;
        }
