/// Fake-provider outcome. `Cancelled` is not a failure: the operation stays
/// durably in `applying` and is requeued on the next launch.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProviderError {
    /// Definite provider-side unavailability; the operation is marked `failed`.
    Unavailable,
    /// Definite provider rejection; the operation is marked `failed`.
    Rejected,
    /// Shutdown cancellation; the operation stays durable for recovery.
    Cancelled,
}

impl ProviderError {
    /// Wire-facing failure discriminant for a definite failure. `Cancelled`
    /// never produces an `OperationFailure`; it is recovered instead.
    pub fn failure_kind(self) -> Option<&'static str> {
        match self {
            ProviderError::Unavailable => Some("provider_unavailable"),
            ProviderError::Rejected => Some("provider_rejected"),
            ProviderError::Cancelled => None,
        }
    }
}
//! One diagnosable log line per storage failure, with no mailbox data.
//!
//! Every storage failure still surfaces as [`MailError::StorageUnavailable`]; the wire error
//! is unchanged. What this module adds is a record of *why*, so a failure can be diagnosed
//! from a log. The privacy promise is enforced structurally: a line is built only from
//! static strings, the call site's `file:line` and the numeric SQLite result codes. Display
//! text of an underlying error is never read, because SQLite messages can quote data such as
//! constraint-violating values or SQL fragments.

