    core.start_worker(fake.clone()).expect("start worker");
    let receipt = core
        .set_archived(&set_archived("conv-01", true, "req-1"))
        .expect("accept");
    let counter = Arc::new(ChangeCounter {
        count: Mutex::new(0),
