        counter.until(|| {
            let snapshot = core.list_conversations().expect("snapshot");
            status_of(&snapshot, &archive_receipt.operation_id) == OperationStatus::Confirmed
                && status_of(&snapshot, &unarchive_receipt.operation_id)
