        serde_json::from_str(legacy).expect("legacy summary deserializes");
    assert!(parsed.primary_correspondent.is_none());
    let json = serde_json::to_string(&parsed).expect("serialize");
    assert!(!json.contains("primaryCorrespondent"));
    core.stop_worker();
}

