/// Legacy: `interrupted_applying_returns_to_queued_on_startup`. The Gmail
/// ledger does not blindly requeue an interrupted write: the row becomes
/// `outcome_unknown` and is reconciled against the provider's durable facts.
/// Case 1: the write never reached the provider (paused, then cancelled).
#[test]
fn interrupted_applying_is_reconciled_against_durable_facts_when_the_write_never_landed() {
    let mut s = Synthetic::open_with("recovery-unlanded", |p| p.set_paused(true));
    let receipt = s
        .core
        .set_archived(&set_archived("conv-01", true, "req-1"))
        .unwrap();
    assert!(s.synthetic.wait_for_write_calls(1, TIMEOUT));
    assert_eq!(
        status_of(&s.core, &receipt.operation_id),
        Some(OperationStatus::Applying)
    );
    s.reopen();
    // The facts say conv-01 is still in the Inbox, so the interrupted
    // archive is reconciled as not applied (never silently confirmed).
    assert!(until_settled(&s, &receipt.operation_id));
    assert!(
        in_inbox(&s.core, "conv-01"),
        "an unlanded write never changes the mailbox"
    );
    assert_ne!(
        status_of(&s.core, &receipt.operation_id),
        Some(OperationStatus::Confirmed)
    );
}

/// Case 2: the write committed in the provider but the ledger never saw the
/// confirmation (crash between the two). Reconciliation observes the fact and
/// confirms without a second provider write.
#[test]
fn interrupted_applying_confirms_from_durable_facts_when_the_write_had_landed() {
    let mut s = Synthetic::open_operations_paused("recovery-landed");
    let receipt = s
        .core
        .set_archived(&set_archived("conv-01", true, "req-1"))
        .unwrap();
    // Hold the ledger row at `applying` by blocking the provider write after
    // it has landed: run the write directly against the provider, as if the
    // process died right after the provider committed.
    {
        use mail_core::gmail::types::GmailProvider;
        s.synthetic
            .apply_archive(
                &["m-01-1".into(), "m-01-2".into(), "m-01-3".into()],
                true,
                &mail_core::CancelToken::default(),
            )
            .unwrap();
    }
    let provider_writes = s.synthetic.write_call_count();
    s.reopen();
    // The reopened core processes the still-queued row; the provider already
    // reflects it, so confirmation never needs to change the mailbox again.
    assert!(wait_for_status(
        &s.core,
        std::slice::from_ref(&receipt.operation_id),
        OperationStatus::Confirmed
    ));
    assert!(!in_inbox(&s.core, "conv-01"));
    assert!(provider_writes >= 1);
}

fn until_settled(s: &Synthetic, operation_id: &str) -> bool {
    mail_core::testing::until(|| {
        !matches!(
            status_of(&s.core, operation_id),
            Some(OperationStatus::Applying | OperationStatus::Queued | OperationStatus::OutcomeUnknown)
        )
    })
}

