    request.cursor = None;
    request.limit = 100;
    assert_eq!(s.core.list_cached_done(&request).unwrap().conversations.len(), 1);
    request.account_id = "foreign".into();
    assert_eq!(s.core.list_cached_done(&request), Err(MailError::NotFound));
