        let receipt = backend
            .set_archived(&SetArchived {
                conversation: conv("conv-01"),
                archived: true,
                request_id: "paused".into(),
            })
            .unwrap();
        // Reads, status and a second command stay responsive while paused.
        assert!(until(|| backend.list_conversations().unwrap().activity.iter().any(|op| {
            op.id == receipt.operation_id && op.status == mail_core::dto::OperationStatus::Applying
        })));
        backend.get_conversation(&conv("conv-02")).unwrap();
        backend.account_status().unwrap();
        let (done_tx, done_rx) = mpsc::channel();
        let stopper = backend.clone();
        std::thread::spawn(move || {
            stopper.stop();
            let _ = done_tx.send(());
        });
        done_rx.recv_timeout(TIMEOUT).expect("stop completes while paused");
